// Mirrors REVIEW_FACETS and the prompts in OpenEngine's
// packages/graph_runtime_langgraph/.../components/{findings,change_prompts}.py
// so the two engines are compared on the same review work.

export type Facet = { id: string; name: string; focus: string; elevated?: boolean };

export const REVIEW_FACETS: Facet[] = [
	{
		id: "security",
		name: "Security",
		elevated: true,
		focus:
			"Look for security vulnerabilities: injection flaws (SQL, command, XSS), authentication and authorization gaps, secrets or credentials in code, unsafe deserialization, path traversal, and any OWASP Top 10 issues. Evaluate whether inputs from external sources are validated and sanitized.",
	},
	{
		id: "bugs",
		name: "Bugs & task adherence",
		focus:
			"Look for correctness bugs, logic errors, off-by-one mistakes, null/None handling gaps, race conditions, and missing error handling. Also verify that the implementation actually does what the original task asked for -- flag anything the task requested that is missing, and anything present that the task did not ask for.",
	},
	{
		id: "performance",
		name: "Performance",
		focus:
			"Look for performance issues: unnecessary allocations, O(n^2) or worse algorithms where better ones are straightforward, missing indexes on queries, unbounded loops, blocking calls in async contexts, and resource leaks (open files, connections, memory).",
	},
	{
		id: "conciseness",
		name: "Conciseness",
		focus:
			"Look for unnecessary complexity: dead code, redundant conditions, over-abstraction, copy-paste duplication that should be a shared function, overly verbose patterns that have a simpler equivalent in the language or framework, and any code that could be removed without changing behavior.",
	},
	{
		id: "dryness",
		name: "DRYness & code duplication",
		focus:
			"Check the changes for DRY (Don't Repeat Yourself) violations and code duplication. Search the repository beyond the changed files for existing helpers, utilities, and equivalent logic that the change could reuse. Look for duplicated business rules and repeated logic introduced by the change, both within the diff and against existing code. Report actionable duplication with the changed location and the existing equivalent's path, explaining what should be reused or consolidated and why. Do not flag unrelated pre-existing duplication or recommend abstractions for merely similar code with different responsibilities.",
	},
];

// Same tiers as REVIEW_MODELS["claude"] in implementation_review_graph.py.
export const modelFor = (facet: Facet) => (facet.elevated ? "opus" : "sonnet");

export type Finding = { tagline: string; description: string; file?: string; line?: number };

export const FINDINGS_SCHEMA = {
	type: "object",
	properties: {
		findings: {
			type: "array",
			items: {
				type: "object",
				properties: {
					tagline: { type: "string" },
					description: { type: "string" },
					file: { type: "string" },
					line: { type: "integer" },
				},
				required: ["tagline", "description"],
			},
		},
	},
	required: ["findings"],
};

export const facetPrompt = (facet: Facet, change: string, task: string) =>
	`Review the implementation in this workspace, focusing exclusively on **${facet.name}**.

${facet.focus}

The change is ${change}. Read the changed code and the code around it before judging. Inspect only: do not edit, revert, commit, or modify anything.

Your acceptance criteria: produce a JSON object {"findings": [...]} of *finding* objects. Each finding has exactly two required fields:
- "tagline": 1-2 lines explaining the issue as you would to a layman
- "description": 1-3 followup lines about what it is and why it is bad

Optional fields (include when applicable):
- "file": the file path the finding relates to
- "line": the line number within that file

If you find nothing worth reporting, return {"findings": []}.

Original task:
${task}`;

export const rerankerPrompt = (sections: string, change: string, task: string, count: number) =>
	`You are a senior reviewer consolidating findings from ${count} specialized reviewers who each examined the same code change from a different angle. Your job is to **somewhat aggressively** squash noise.

Remove any finding that is:
- A nitpick or stylistic preference
- A duplicate of another finding (even across facets)
- About a hypothetical issue that is extremely unlikely in practice
- Not actionable -- the author cannot do anything concrete about it
- Already handled by existing code the reviewer missed

Keep findings a senior engineer would genuinely want fixed before merging, and concrete, actionable findings that are likely real even when they are minor. When in doubt about one of those, keep it.

Return the surviving findings as {"findings": [...]} with the same fields.

${sections}
The change is ${change}.

Original task:
${task}`;

import { spawn } from "node:child_process";
import { FINDINGS_SCHEMA, type Finding } from "./facets.ts";

// Read-only tool surface: the reviewers inspect, they never edit.
const READ_ONLY_TOOLS = [
	"Read",
	"Grep",
	"Glob",
	"Bash(git diff:*)",
	"Bash(git log:*)",
	"Bash(git show:*)",
	"Bash(git status:*)",
];

export type AgentResult = { findings: Finding[]; costUsd: number; durationMs: number; turns: number };

/** Run one headless Claude Code session in `cwd` and return its structured findings. */
export function runClaude(prompt: string, model: string, cwd: string, signal?: AbortSignal): Promise<AgentResult> {
	const args = [
		"-p",
		prompt,
		"--model",
		model,
		"--output-format",
		"json",
		"--json-schema",
		JSON.stringify(FINDINGS_SCHEMA),
		"--allowedTools",
		...READ_ONLY_TOOLS,
		"--disallowedTools",
		"Edit",
		"Write",
		"NotebookEdit",
	];
	return new Promise((resolve, reject) => {
		const child = spawn("claude", args, { cwd, signal, stdio: ["ignore", "pipe", "pipe"] });
		let out = "";
		let err = "";
		child.stdout.on("data", (d) => (out += d));
		child.stderr.on("data", (d) => (err += d));
		child.on("error", reject);
		child.on("close", (code) => {
			if (code !== 0) return reject(new Error(`claude exited ${code}: ${err || out}`.slice(0, 2000)));
			try {
				const res = JSON.parse(out);
				if (res.is_error) return reject(new Error(`claude error: ${res.result}`));
				resolve({
					findings: res.structured_output?.findings ?? [],
					costUsd: res.total_cost_usd ?? 0,
					durationMs: res.duration_ms ?? 0,
					turns: res.num_turns ?? 0,
				});
			} catch (e) {
				reject(new Error(`unparseable claude output: ${out.slice(0, 500)}`));
			}
		});
	});
}

import { execFileSync } from "node:child_process";
import { queue, setup, workflow } from "@rivet-dev/workflows";
import { runClaude, type AgentResult } from "./claude.ts";
import { REVIEW_FACETS, facetPrompt, modelFor, rerankerPrompt, type Finding } from "./facets.ts";

export type ReviewRequest = {
	repo: string; // absolute path to a git checkout
	base: string; // e.g. "main"
	head: string; // e.g. "HEAD" or a branch
	task: string; // what the change was meant to do
};

type FacetOutcome = { ok: true; result: AgentResult } | { ok: false; error: string };

// LLM steps run for minutes; Rivet's default step timeout is 30s.
const AGENT_STEP = { timeout: 20 * 60_000, maxRetries: 1 };

export const prReview = workflow({
	state: {
		status: "waiting" as "waiting" | "reviewing" | "reranking" | "complete" | "failed",
		request: null as ReviewRequest | null,
		diffStat: "",
		facets: {} as Record<string, FacetOutcome>,
		kept: [] as Finding[],
		rerank: null as AgentResult | null,
		startedAt: 0,
		finishedAt: 0,
	},
	queues: {
		review: queue<ReviewRequest>(),
	},
	run: async (ctx) => {
		const msg = await ctx.queue.next("wait-request");
		const req = msg.body;
		const change = `the diff \`git diff ${req.base}...${req.head}\` in this repository`;

		await ctx.step("capture-diff", async (step) => {
			step.state.request = req;
			step.state.startedAt = Date.now();
			step.state.status = "reviewing";
			step.state.diffStat = execFileSync("git", ["diff", "--stat", `${req.base}...${req.head}`], {
				cwd: req.repo,
				encoding: "utf8",
			});
		});

		// Fan out: one durable branch per facet. Each branch's step is recorded
		// independently, so a crash mid-review replays only unfinished facets.
		const branches = Object.fromEntries(
			REVIEW_FACETS.map((facet) => [
				facet.id,
				{
					run: async (b: { tryStep: typeof ctx.tryStep }) => {
						const r = await b.tryStep({
							name: `review-${facet.id}`,
							...AGENT_STEP,
							run: () => runClaude(facetPrompt(facet, change, req.task), modelFor(facet), req.repo),
						});
						return (r.ok ? { ok: true, result: r.value } : { ok: false, error: String(r.failure.error?.message ?? r.failure.kind) }) as FacetOutcome;
					},
				},
			]),
		);
		const outcomes = (await ctx.join("review-facets", branches as any)) as Record<string, FacetOutcome>;

		// Fan in: rerank across facets.
		const sections = REVIEW_FACETS.map((f) => {
			const o = outcomes[f.id];
			const body = o.ok ? JSON.stringify(o.result.findings, null, 2) : `(reviewer failed: ${o.error})`;
			return `## ${f.name} findings\n${body}\n`;
		}).join("\n");

		await ctx.step("record-facets", async (step) => {
			step.state.facets = outcomes;
			step.state.status = "reranking";
		});

		const rerank = await ctx.step({
			name: "rerank",
			...AGENT_STEP,
			run: () => runClaude(rerankerPrompt(sections, change, req.task, REVIEW_FACETS.length), "sonnet", req.repo),
		});

		await ctx.step("finish", async (step) => {
			step.state.rerank = rerank;
			step.state.kept = rerank.findings;
			step.state.status = "complete";
			step.state.finishedAt = Date.now();
		});
	},
	actions: {
		getState: (c) => c.state,
	},
});

export const registry = setup({ use: { prReview } });

// Usage: tsx src/client.ts <repo> <base> <head> "<task>" [runKey]
import { setTimeout as sleep } from "node:timers/promises";
import { createClient } from "@rivet-dev/workflows";
import type { registry } from "./registry.ts";

const [repo, base = "main", head = "HEAD", task = "(no task given)", key = `review-${Date.now()}`] = process.argv.slice(2);
if (!repo) {
	console.error('usage: tsx src/client.ts <repo> <base> <head> "<task>" [runKey]');
	process.exit(2);
}

const client = createClient<typeof registry>(process.env.RIVET_ENDPOINT ?? "http://localhost:6420");
const handle = client.prReview.getOrCreate([key]);

const initial = await handle.getState();
if (initial.status === "waiting") await handle.send("review", { repo, base, head, task });
console.log(`run ${key}: ${initial.status === "waiting" ? "started" : `reattached (${initial.status})`}`);

let last = "";
for (;;) {
	const s = await handle.getState();
	const line = `${s.status} | facets done: ${Object.keys(s.facets).length}/5`;
	if (line !== last) console.log(`[${new Date().toISOString()}] ${line}`), (last = line);
	if (s.status === "complete" || s.status === "failed") {
		console.log(`\n${s.diffStat}`);
		for (const [id, o] of Object.entries(s.facets)) {
			console.log(o.ok
				? `- ${id}: ${o.result.findings.length} findings, ${(o.result.durationMs / 1000).toFixed(0)}s, $${o.result.costUsd.toFixed(3)}`
				: `- ${id}: FAILED ${o.error}`);
		}
		console.log(`\nKept after rerank (${s.kept.length}):`);
		for (const f of s.kept) console.log(`* ${f.file ? `${f.file}${f.line ? `:${f.line}` : ""} ` : ""}${f.tagline}\n  ${f.description}`);
		console.log(`\nwall clock: ${((s.finishedAt - s.startedAt) / 1000).toFixed(0)}s`);
		break;
	}
	await sleep(3000);
}

