import { execFileSync } from "node:child_process";

/**
 * Credentials for the agents inside the box, discovered from this machine's
 * Claude Code / Codex logins by `sandbox-agent credentials extract-env`.
 *
 * A Claude subscription login comes back as an OAuth token (`sk-ant-oat…`)
 * under ANTHROPIC_API_KEY. Claude Code only accepts that as
 * CLAUDE_CODE_OAUTH_TOKEN, so it is moved there; a real API key is passed as is.
 */
export function agentEnv(): Record<string, string> {
	const out = execFileSync("npx", ["sandbox-agent", "credentials", "extract-env"], { encoding: "utf8" });
	const found: Record<string, string> = {};
	for (const line of out.split("\n")) {
		const m = line.match(/^(?:export )?([A-Z_]+)=(.*)$/);
		if (m) found[m[1]] = m[2].replace(/^['"]|['"]$/g, "");
	}
	const env: Record<string, string> = {};
	const claude = found.ANTHROPIC_API_KEY ?? found.CLAUDE_API_KEY;
	if (claude?.startsWith("sk-ant-oat")) env.CLAUDE_CODE_OAUTH_TOKEN = claude;
	else if (claude) env.ANTHROPIC_API_KEY = claude;
	if (!claude) throw new Error("no Claude credentials found by `sandbox-agent credentials extract-env`");
	return env;
}

import { createServer } from "node:net";
import { fileURLToPath } from "node:url";
import { SimpleBox } from "@boxlite-ai/boxlite";
import { SandboxAgent } from "sandbox-agent";
import { agentEnv } from "./credentials.ts";

const OCI_IMAGE = fileURLToPath(new URL("../box/oci-image", import.meta.url));
const GUEST_PORT = 2468;
/** Where the host repository is mounted, read-only. */
export const SRC = "/src";
/** Where the review checkout and its per-reviewer worktrees live. */
export const WORK = "/work/repo";

export type BoxInfo = { name: string; port: number };

export const freePort = () =>
	new Promise<number>((resolve, reject) => {
		const s = createServer();
		s.listen(0, "127.0.0.1", () => {
			const { port } = s.address() as { port: number };
			s.close(() => resolve(port));
		});
		s.on("error", reject);
	});

/**
 * Open (or reattach to) the micro-VM for one review run. The box is named and
 * detached, so it outlives this process: when Rivet replays the workflow
 * after a crash, `reuseExisting` hands back the same VM with its checkout and
 * Sandbox Agent server still in it.
 */
export function openBox(info: BoxInfo, repo: string) {
	return new SimpleBox({
		name: info.name,
		rootfsPath: OCI_IMAGE,
		reuseExisting: true,
		detach: true,
		autoRemove: false,
		memoryMib: 4096,
		cpus: 4,
		diskSizeGb: 8,
		env: agentEnv(),
		volumes: [{ hostPath: repo, guestPath: SRC, readOnly: true }],
		ports: [{ hostPort: info.port, guestPort: GUEST_PORT }],
	});
}

export async function sh(box: SimpleBox, script: string) {
	const r = await box.exec("sh", ["-c", script], undefined);
	if (r.exitCode !== 0) throw new Error(`box command failed (${r.exitCode}): ${script}\n${r.stderr || r.stdout}`);
	return r.stdout;
}

/** Start Sandbox Agent inside the box if it isn't already up, and connect. */
export async function connectAgent(box: SimpleBox, port: number): Promise<SandboxAgent> {
	await sh(
		box,
		`pgrep -f "sandbox-agent server" >/dev/null || (nohup sandbox-agent server --no-token --host 0.0.0.0 --port ${GUEST_PORT} >/tmp/sandbox-agent.log 2>&1 &)`,
	);
	const baseUrl = `http://127.0.0.1:${port}`;
	for (let i = 0; ; i++) {
		try {
			const r = await fetch(`${baseUrl}/v1/health`);
			if (r.ok) break;
		} catch {}
		if (i > 60) throw new Error(`sandbox-agent did not come up on ${baseUrl}: ${await sh(box, "tail -20 /tmp/sandbox-agent.log")}`);
		await new Promise((r) => setTimeout(r, 500));
	}
	return SandboxAgent.connect({ baseUrl });
}

// Boot a box, start Sandbox Agent, and ask Claude one question in the mounted repo.
// Usage: tsx src/smoke.ts [repo]
import { connectAgent, freePort, openBox, sh, SRC } from "./box.ts";

const repo = process.argv[2] ?? process.cwd();
const info = { name: `smoke-${Date.now()}`, port: await freePort() };
const box = openBox(info, repo);
try {
	console.log("box:", (await sh(box, `uname -a && git -C ${SRC} log --oneline -1`)).trim());
	const sdk = await connectAgent(box, info.port);
	const session = await sdk.createSession({ agent: "claude", model: "haiku", cwd: SRC, mode: "default" });
	session.onPermissionRequest((req) => void session.respondPermission(req.id, "once"));
	let text = "";
	session.onEvent((e: any) => {
		const u = e.payload?.params?.update;
		if (u?.sessionUpdate === "agent_message_chunk" && u.content?.type === "text") text += u.content.text;
	});
	const res = await session.prompt([{ type: "text", text: "In one sentence: what is this repository? Read the README." }]);
	console.log("stopReason:", res.stopReason);
	console.log("answer:", text.trim());
} finally {
	await box.stop();
}

