import { execFileSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const TOKEN_FILE = fileURLToPath(new URL("../.claude-token", import.meta.url));

/**
 * Credentials for the agents inside the box.
 *
 * 1. CLAUDE_CODE_OAUTH_TOKEN / ANTHROPIC_API_KEY from the environment, or a
 *    long-lived token saved in `.claude-token` (from `claude setup-token`).
 * 2. Otherwise `sandbox-agent credentials extract-env`. On macOS this reads
 *    ~/.claude/.credentials.json, which Claude Code stops refreshing once the
 *    live login moves to the Keychain -- so the token it returns is usually an
 *    expired access token (401 "OAuth access token has expired").
 *
 * A subscription token (`sk-ant-oat…`) is only accepted by Claude Code as
 * CLAUDE_CODE_OAUTH_TOKEN, so it is moved there; a real API key is passed as is.
 */
export function agentEnv(): Record<string, string> {
	const explicit =
		process.env.CLAUDE_CODE_OAUTH_TOKEN ??
		process.env.ANTHROPIC_API_KEY ??
		(existsSync(TOKEN_FILE) ? readFileSync(TOKEN_FILE, "utf8").trim() : undefined);
	const token = explicit || extracted();
	if (!token) throw new Error("no Claude credentials: run `claude setup-token` and save it to .claude-token");
	return token.startsWith("sk-ant-oat") ? { CLAUDE_CODE_OAUTH_TOKEN: token } : { ANTHROPIC_API_KEY: token };
}

function extracted(): string | undefined {
	const out = execFileSync("npx", ["sandbox-agent", "credentials", "extract-env"], { encoding: "utf8" });
	const found: Record<string, string> = {};
	for (const line of out.split("\n")) {
		const m = line.match(/^(?:export )?([A-Z_]+)=(.*)$/);
		if (m) found[m[1]] = m[2].replace(/^['"]|['"]$/g, "");
	}
	return found.ANTHROPIC_API_KEY ?? found.CLAUDE_API_KEY;
}

import type { SimpleBox } from "@boxlite-ai/boxlite";
import type { SandboxAgent, Session } from "sandbox-agent";
import { connectAgent, openBox, type BoxInfo } from "./box.ts";
import type { Finding } from "./facets.ts";

// ---------------------------------------------------------------------------
// Process-local handles. A box and its Sandbox Agent server outlive this
// process; these are just reconnected on first use after a restart.
// ---------------------------------------------------------------------------

const boxes = new Map<string, { box: SimpleBox; sdk: Promise<SandboxAgent> }>();

export function agentFor(info: BoxInfo, repo: string) {
	let entry = boxes.get(info.name);
	if (!entry) {
		const box = openBox(info, repo);
		entry = { box, sdk: connectAgent(box, info.port) };
		boxes.set(info.name, entry);
	}
	return entry;
}

export async function closeBox(info: BoxInfo, repo: string) {
	const { box } = agentFor(info, repo);
	boxes.delete(info.name);
	await box.stop();
}

// ---------------------------------------------------------------------------
// Steering. Sandbox Agent refuses `session/cancel` ("use destroySession"), and a
// Rivet step can't see queue messages while it runs, so a steer is parked here
// and delivered as the next prompt when the agent's current turn ends.
// ---------------------------------------------------------------------------

const steering = new Map<string, string[]>();

export function steer(sessionId: string, text: string) {
	steering.set(sessionId, [...(steering.get(sessionId) ?? []), text]);
}

const takeSteering = (sessionId: string) => {
	const pending = steering.get(sessionId) ?? [];
	steering.delete(sessionId);
	return pending;
};

// ---------------------------------------------------------------------------
// Permissions: reviewers inspect, they never change anything.
// ---------------------------------------------------------------------------

const READ_KINDS = new Set(["read", "search", "think", "fetch"]);
const READ_COMMAND = /^\s*(git (diff|log|show|status|blame|ls-files|rev-parse)|rg|grep|ls|cat|head|tail|wc|find|tree)\b/;

function allowed(toolCall: any): boolean {
	if (READ_KINDS.has(toolCall?.kind)) return true;
	const command = toolCall?.rawInput?.command;
	return toolCall?.kind === "execute" && typeof command === "string" && READ_COMMAND.test(command) && !/[;&|>`$]/.test(command);
}

// ---------------------------------------------------------------------------
// One reviewer session.
// ---------------------------------------------------------------------------

export type ReviewResult = {
	sessionId: string;
	findings: Finding[];
	turns: number;
	durationMs: number;
	steered: string[];
	denied: string[];
};

const JSON_ONLY = 'Reply with only the JSON object {"findings": [...]}, no prose and no code fence.';

export async function review(opts: {
	sdk: SandboxAgent;
	sessionId: string;
	cwd: string;
	model: string;
	prompt: string;
}): Promise<ReviewResult> {
	const started = Date.now();
	const session: Session = await opts.sdk.resumeOrCreateSession({
		id: opts.sessionId,
		agent: "claude",
		model: opts.model,
		mode: "default",
		cwd: opts.cwd,
	});
	const denied: string[] = [];
	const steered: string[] = [];
	session.onPermissionRequest((req) => {
		const ok = allowed(req.toolCall);
		if (!ok) denied.push(req.toolCall?.title ?? "unknown tool");
		void session.respondPermission(req.id, ok ? "once" : "reject");
	});
	let reply = "";
	session.onEvent((e: any) => {
		const u = e.payload?.params?.update;
		if (u?.sessionUpdate === "agent_message_chunk" && u.content?.type === "text") reply += u.content.text;
	});

	let turns = 0;
	const turn = async (text: string) => {
		reply = "";
		turns++;
		await session.prompt([{ type: "text", text }]);
		return reply;
	};

	let last = await turn(`${opts.prompt}\n\n${JSON_ONLY}`);
	// Deliver any steering that arrived during the turn, then ask again for the result.
	for (let pending = takeSteering(opts.sessionId); pending.length; pending = takeSteering(opts.sessionId)) {
		steered.push(...pending);
		last = await turn(`Steering from the operator:\n${pending.join("\n")}\n\nApply it, then give your final findings. ${JSON_ONLY}`);
	}
	let findings = parseFindings(last);
	if (!findings) {
		last = await turn(`That was not valid JSON. ${JSON_ONLY}`);
		findings = parseFindings(last);
	}
	if (!findings) throw new Error(`reviewer did not return findings JSON: ${last.slice(0, 300)}`);
	return { sessionId: opts.sessionId, findings, turns, durationMs: Date.now() - started, steered, denied };
}

function parseFindings(text: string): Finding[] | null {
	const start = text.indexOf("{");
	const end = text.lastIndexOf("}");
	if (start < 0 || end <= start) return null;
	try {
		const parsed = JSON.parse(text.slice(start, end + 1));
		return Array.isArray(parsed.findings) ? parsed.findings : null;
	} catch {
		return null;
	}
}

import { execFileSync } from "node:child_process";
import { queue, setup, workflow } from "@rivet-dev/workflows";
import { agentFor, closeBox, review, steer, type ReviewResult } from "./agent.ts";
import { freePort, sh, SRC, WORK, type BoxInfo } from "./box.ts";
import { REVIEW_FACETS, facetPrompt, modelFor, rerankerPrompt, type Finding } from "./facets.ts";

export type ReviewRequest = {
	key: string; // the run's key; names the box and the agent sessions
	repo: string; // absolute path to a git checkout on the host
	base: string; // e.g. "main"
	head: string; // a committed ref, e.g. a branch
	task: string; // what the change was meant to do
};

type FacetOutcome = { ok: true; result: ReviewResult } | { ok: false; error: string };

// LLM steps run for minutes; Rivet's default step timeout is 30s.
const AGENT_STEP = { timeout: 20 * 60_000, maxRetries: 1 };

const sessionId = (key: string, facet: string) => `${key}-${facet}`;
const worktree = (facet: string) => `/work/wt/${facet}`;

export const prReview = workflow({
	state: {
		status: "waiting" as "waiting" | "provisioning" | "reviewing" | "reranking" | "complete" | "failed",
		request: null as ReviewRequest | null,
		box: null as BoxInfo | null,
		baseSha: "",
		headSha: "",
		diffStat: "",
		facets: {} as Record<string, FacetOutcome>,
		kept: [] as Finding[],
		rerank: null as ReviewResult | null,
		startedAt: 0,
		finishedAt: 0,
	},
	queues: {
		review: queue<ReviewRequest>(),
	},
	run: async (ctx) => {
		const msg = await ctx.queue.next("wait-request");
		const req = msg.body;

		// Resolved on the host, recorded once: every later step and every
		// replay sees the same commits even if the branch moves.
		const { box, baseSha, headSha } = await ctx.step("resolve", async (step) => {
			const git = (...a: string[]) => execFileSync("git", a, { cwd: req.repo, encoding: "utf8" }).trim();
			const resolved = {
				box: { name: `review-${req.key}`, port: await freePort() },
				baseSha: git("merge-base", req.base, req.head),
				headSha: git("rev-parse", req.head),
			};
			step.state.request = req;
			step.state.startedAt = Date.now();
			step.state.status = "provisioning";
			Object.assign(step.state, resolved);
			step.state.diffStat = git("diff", "--stat", `${resolved.baseSha}...${resolved.headSha}`);
			return resolved;
		});
		const change = `the diff \`git diff ${baseSha}...${headSha}\` in this repository`;

		// One micro-VM per run: the host repo mounted read-only at /src, a clone
		// at the head commit, and a detached worktree per reviewer. Idempotent,
		// so a replay after a crash reattaches to the same box and skips work done.
		await ctx.step({
			name: "provision-box",
			...AGENT_STEP,
			run: async () => {
				const { box: vm } = agentFor(box, req.repo);
				await sh(vm, [
					`[ -d ${WORK} ] || git clone --quiet --no-checkout ${SRC} ${WORK}`,
					`git -C ${WORK} checkout --quiet --detach ${headSha}`,
					...REVIEW_FACETS.map(
						(f) => `[ -d ${worktree(f.id)} ] || git -C ${WORK} worktree add --quiet --detach ${worktree(f.id)} ${headSha}`,
					),
				].join(" && "));
				await agentFor(box, req.repo).sdk;
			},
		});
		await ctx.step("reviewing", async (step) => {
			step.state.status = "reviewing";
		});

		// Fan out: one durable branch per facet, each a Claude Code session in
		// its own worktree inside the box.
		const branches = Object.fromEntries(
			REVIEW_FACETS.map((facet) => [
				facet.id,
				{
					run: async (b: { tryStep: typeof ctx.tryStep }) => {
						const r = await b.tryStep({
							name: `review-${facet.id}`,
							...AGENT_STEP,
							run: async () =>
								review({
									sdk: await agentFor(box, req.repo).sdk,
									sessionId: sessionId(req.key, facet.id),
									cwd: worktree(facet.id),
									model: modelFor(facet),
									prompt: facetPrompt(facet, change, req.task),
								}),
						});
						return (r.ok ? { ok: true, result: r.value } : { ok: false, error: String(r.failure.error?.message ?? r.failure.kind) }) as FacetOutcome;
					},
				},
			]),
		);
		const outcomes = (await ctx.join("review-facets", branches as any)) as Record<string, FacetOutcome>;

		await ctx.step("record-facets", async (step) => {
			step.state.facets = outcomes;
			step.state.status = "reranking";
		});

		// Fan in: rerank across facets, in the main checkout.
		const sections = REVIEW_FACETS.map((f) => {
			const o = outcomes[f.id];
			const body = o.ok ? JSON.stringify(o.result.findings, null, 2) : `(reviewer failed: ${o.error})`;
			return `## ${f.name} findings\n${body}\n`;
		}).join("\n");
		const rerank = await ctx.step({
			name: "rerank",
			...AGENT_STEP,
			run: async () =>
				review({
					sdk: await agentFor(box, req.repo).sdk,
					sessionId: sessionId(req.key, "reranker"),
					cwd: WORK,
					model: "sonnet",
					prompt: rerankerPrompt(sections, change, req.task, REVIEW_FACETS.length),
				}),
		});

		await ctx.step("finish", async (step) => {
			step.state.rerank = rerank;
			step.state.kept = rerank.findings;
			step.state.status = "complete";
			step.state.finishedAt = Date.now();
		});
		await ctx.step("close-box", () => closeBox(box, req.repo));
	},
	actions: {
		getState: (c) => c.state,
		/** Queue a message for one reviewer; it is delivered when its current turn ends. */
		steer: (c, facet: string, text: string) => {
			if (!c.state.request) throw new Error("run has not started");
			steer(sessionId(c.state.request.key, facet), text);
			return { queuedFor: sessionId(c.state.request.key, facet) };
		},
	},
});

export const registry = setup({ use: { prReview } });

