// Right after `npm run server` the engine answers before its runner registers
// (no_runner_config_configured); retry through that window.
async function firstState() {
	for (let i = 0; ; i++) {
		try {
			return await handle.getState();
		} catch (e: any) {
			if (e?.code !== "no_runner_config_configured" || i >= 20) throw e;
			await sleep(1000);
		}
	}
}
const initial = await firstState();
if (initial.status === "waiting") await handle.send("review", { key, repo, base, head, task });
console.log(`run ${key}: ${initial.status === "waiting" ? "started" : `reattached (${initial.status})`}`);
console.log(`steer a reviewer with: npm run steer -- ${key} <facet> "<message>"`);

let last = "";
for (;;) {
	const s = await handle.getState();
	const line = `${s.status} | facets done: ${Object.keys(s.facets).length}/5`;
	if (line !== last) console.log(`[${new Date().toISOString()}] ${line}`), (last = line);
	if (s.status === "complete" || s.status === "failed") {
		console.log(`\n${s.headSha.slice(0, 8)} vs ${s.baseSha.slice(0, 8)}\n${s.diffStat}\n`);
		for (const [id, o] of Object.entries(s.facets as Record<string, any>)) {
			const r = o.result;
			console.log(o.ok
				? `- ${id}: ${r.findings.length} findings, ${(r.durationMs / 1000).toFixed(0)}s, ${r.turns} turns` +
					(r.steered.length ? `, steered ${r.steered.length}x` : "") +
					(r.denied.length ? `, denied: ${r.denied.join("; ")}` : "")
				: `- ${id}: FAILED ${o.error}`);
		}
		console.log(`\nKept after rerank (${s.kept.length}):`);
		for (const f of s.kept) console.log(`* ${f.file ? `${f.file}${f.line ? `:${f.line}` : ""} ` : ""}${f.tagline}\n  ${f.description}`);
		console.log(`\nwall clock: ${((s.finishedAt - s.startedAt) / 1000).toFixed(0)}s`);
		break;
	}
	await sleep(3000);
}
