import type { SimpleBox } from "@boxlite-ai/boxlite";
import type { SandboxAgent, Session } from "sandbox-agent";
import { connectAgent, destroyBox, openBox, type BoxInfo, type Mounts } from "./box.ts";
import type { Finding } from "./facets.ts";

// ---------------------------------------------------------------------------
// Process-local handles. A box and its Sandbox Agent server outlive this
// process; these are just reconnected on first use after a restart.
// ---------------------------------------------------------------------------

const boxes = new Map<string, { box: SimpleBox; sdk: Promise<SandboxAgent> }>();

export function agentFor(info: BoxInfo, mounts: Mounts) {
	let entry = boxes.get(info.name);
	if (!entry) {
		const box = openBox(info, mounts);
		entry = { box, sdk: connectAgent(box, info.port) };
		boxes.set(info.name, entry);
	}
	return entry;
}

export async function closeBox(info: BoxInfo, mounts: Mounts) {
	const { box } = agentFor(info, mounts);
	boxes.delete(info.name);
	await destroyBox(box);
}

// ---------------------------------------------------------------------------
// Steering. Sandbox Agent refuses `session/cancel` ("use destroySession"), and a
// Rivet step can't see queue messages while it runs, so a steer is parked here
// and delivered as the next prompt when the agent's current turn ends.
// ---------------------------------------------------------------------------

const steering = new Map<string, string[]>();

export function steer(sessionId: string, text: string) {
	steering.set(sessionId, [...(steering.get(sessionId) ?? []), text]);
}

const takeSteering = (sessionId: string) => {
	const pending = steering.get(sessionId) ?? [];
	steering.delete(sessionId);
	return pending;
};

// ---------------------------------------------------------------------------
// Permissions.
// ---------------------------------------------------------------------------

type Policy = (toolCall: any, cwd: string) => boolean;

const READ_KINDS = new Set(["read", "search", "think", "fetch"]);
const READ_COMMAND = /^\s*(git (diff|log|show|status|blame|ls-files|rev-parse)|rg|grep|ls|cat|head|tail|wc|find|tree)\b/;
/** The workflow owns history and the export: the implementer may not move it. */
const GIT_HISTORY = /\bgit\s+(push|commit|reset|checkout|switch|rebase|merge|branch|tag|worktree|remote|config|stash|clean)\b|\/out\b/;

const command = (toolCall: any): string | undefined =>
	typeof toolCall?.rawInput?.command === "string" ? toolCall.rawInput.command : undefined;

const inside = (toolCall: any, cwd: string) =>
	(toolCall?.locations ?? []).every((l: any) => typeof l?.path === "string" && (l.path === cwd || l.path.startsWith(`${cwd}/`)));

/** Reviewers inspect, they never change anything. */
export const readOnly: Policy = (toolCall) => {
	if (READ_KINDS.has(toolCall?.kind)) return true;
	const cmd = command(toolCall);
	return toolCall?.kind === "execute" && !!cmd && READ_COMMAND.test(cmd) && !/[;&|>`$]/.test(cmd);
};

/**
 * The implementer edits inside its worktree and runs anything (it is in a VM
 * whose only writable host path is the run's outbox) except git commands that
 * move history, and anything naming /out.
 */
export const implementer: Policy = (toolCall, cwd) => {
	const kind = toolCall?.kind;
	if (READ_KINDS.has(kind)) return true;
	if (kind === "edit" || kind === "delete" || kind === "move") return inside(toolCall, cwd);
	if (kind === "execute") return !GIT_HISTORY.test(command(toolCall) ?? "");
	return kind === "other";
};

// ---------------------------------------------------------------------------
// Sessions.
// ---------------------------------------------------------------------------

type SessionOpts = { sdk: SandboxAgent; sessionId: string; cwd: string; model: string; policy: Policy };

export type Transcript = { sessionId: string; turns: number; durationMs: number; steered: string[]; denied: string[] };

async function open(opts: SessionOpts) {
	const session: Session = await opts.sdk.resumeOrCreateSession({
		id: opts.sessionId,
		agent: "claude",
		model: opts.model,
		mode: "default",
		cwd: opts.cwd,
	});
	const t: Transcript = { sessionId: opts.sessionId, turns: 0, durationMs: 0, steered: [], denied: [] };
	const started = Date.now();
	session.onPermissionRequest((req) => {
		const ok = opts.policy(req.toolCall, opts.cwd);
		if (!ok) t.denied.push(command(req.toolCall) ?? req.toolCall?.title ?? "unknown tool");
		void session.respondPermission(req.id, ok ? "once" : "reject");
	});
	let reply = "";
	session.onEvent((e: any) => {
		const u = e.payload?.params?.update;
		if (u?.sessionUpdate === "agent_message_chunk" && u.content?.type === "text") reply += u.content.text;
	});
	const turn = async (text: string) => {
		reply = "";
		t.turns++;
		await session.prompt([{ type: "text", text }]);
		t.durationMs = Date.now() - started;
		return reply;
	};
	/** Deliver steering that arrived during a turn, re-asking with `then` after it. */
	const drainSteering = async (last: string, then: string) => {
		for (let pending = takeSteering(opts.sessionId); pending.length; pending = takeSteering(opts.sessionId)) {
			t.steered.push(...pending);
			last = await turn(`Steering from the operator:\n${pending.join("\n")}\n\nApply it, then ${then}`);
		}
		return last;
	};
	return { t, turn, drainSteering };
}

export type ReviewResult = Transcript & { findings: Finding[] };

const JSON_ONLY = 'Reply with only the JSON object {"findings": [...]}, no prose and no code fence.';

export async function review(opts: Omit<SessionOpts, "policy"> & { prompt: string }): Promise<ReviewResult> {
	const { t, turn, drainSteering } = await open({ ...opts, policy: readOnly });
	let last = await turn(`${opts.prompt}\n\n${JSON_ONLY}`);
	last = await drainSteering(last, `give your final findings. ${JSON_ONLY}`);
	let findings = parseFindings(last);
	if (!findings) findings = parseFindings(await turn(`That was not valid JSON. ${JSON_ONLY}`));
	if (!findings) throw new Error(`reviewer did not return findings JSON: ${last.slice(0, 300)}`);
	return { ...t, findings };
}

export type ImplementResult = Transcript & { summary: string };

export async function implement(opts: Omit<SessionOpts, "policy"> & { prompt: string }): Promise<ImplementResult> {
	const { t, turn, drainSteering } = await open({ ...opts, policy: implementer });
	let summary = await turn(opts.prompt);
	summary = await drainSteering(summary, "summarize what you changed and the test results.");
	return { ...t, summary: summary.trim() };
}

function parseFindings(text: string): Finding[] | null {
	const start = text.indexOf("{");
	const end = text.lastIndexOf("}");
	if (start < 0 || end <= start) return null;
	try {
		const parsed = JSON.parse(text.slice(start, end + 1));
		return Array.isArray(parsed.findings) ? parsed.findings : null;
	} catch {
		return null;
	}
}
