// Usage:
//   tsx src/client.ts implement <repo> <base> "<task>" [runKey]
//   tsx src/client.ts review    <repo> <base> <head> "<task>" [runKey]
import { setTimeout as sleep } from "node:timers/promises";
import { createClient } from "rivetkit/client";
import type { registry, ReviewRequest } from "./registry.ts";

const [mode, repo, base, ...rest] = process.argv.slice(2);
const implementing = mode === "implement";
const [head, task, key = `r${Date.now()}`] = implementing ? ["", rest[0], rest[1]] : rest;
if ((mode !== "implement" && mode !== "review") || !repo || !base || !task) {
	console.error('usage: tsx src/client.ts implement <repo> <base> "<task>" [runKey]');
	console.error('       tsx src/client.ts review    <repo> <base> <head> "<task>" [runKey]');
	process.exit(2);
}

const client = createClient<typeof registry>(process.env.RIVET_ENDPOINT ?? "http://localhost:6420");
const handle = client.prReview.getOrCreate([key]);

// Right after `npm run server` the engine answers before its runner registers
// (no_runner_config_configured); retry through that window.
async function firstState() {
	for (let i = 0; ; i++) {
		try {
			return await handle.getState();
		} catch (e: any) {
			if (e?.code !== "no_runner_config_configured" || i >= 20) throw e;
			await sleep(1000);
		}
	}
}
const initial = await firstState();
const request: ReviewRequest = { key, mode, repo, base, head, task };
if (initial.status === "waiting") await (handle as any).send("review", request);
console.log(`run ${key} (${mode}): ${initial.status === "waiting" ? "started" : `reattached (${initial.status})`}`);
console.log(`steer an agent with: npm run steer -- ${key} <${implementing ? "impl|" : ""}facet|reranker> "<message>"`);

const transcript = (r: any) =>
	`${(r.durationMs / 1000).toFixed(0)}s, ${r.turns} turns` +
	(r.steered.length ? `, steered ${r.steered.length}x` : "") +
	(r.denied.length ? `, denied: ${r.denied.join("; ")}` : "");

let last = "";
for (;;) {
	const s = await handle.getState();
	const line = `${s.status}${s.status === "reviewing" ? ` | facets done: ${Object.keys(s.facets).length}/5` : ""}`;
	if (line !== last) console.log(`[${new Date().toISOString()}] ${line}`), (last = line);
	if (s.status === "complete" || s.status === "failed") {
		if (s.implementation) {
			console.log(`\nImplementation (${transcript(s.implementation)}):\n${s.implementation.summary}`);
			console.log(`\nCommitted ${s.headSha.slice(0, 8)} on ${s.baseSha.slice(0, 8)}; exported to ${s.exportRef}`);
		}
		console.log(`\n${s.diffStat}\n`);
		for (const [id, o] of Object.entries(s.facets as Record<string, any>)) {
			console.log(o.ok ? `- ${id}: ${o.result.findings.length} findings, ${transcript(o.result)}` : `- ${id}: FAILED ${o.error}`);
		}
		console.log(`\nKept after rerank (${s.kept.length}):`);
		for (const f of s.kept) console.log(`* ${f.file ? `${f.file}${f.line ? `:${f.line}` : ""} ` : ""}${f.tagline}\n  ${f.description}`);
		console.log(`\nwall clock: ${((s.finishedAt - s.startedAt) / 1000).toFixed(0)}s`);
		if (s.exportRef) {
			const [outbox, ref] = s.exportRef.split(" ");
			console.log(`\nInspect the change:  git -C ${outbox} show ${ref}`);
			console.log(`Bring it to the repo: git -C ${repo} fetch ${outbox} ${ref}:${ref}`);
		}
		break;
	}
	await sleep(3000);
}
