import { execFileSync } from "node:child_process";
import { mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { CriticalError, JoinError, queue, setup, StepExhaustedError, workflow } from "@rivet-dev/workflows";
import { agentFor, closeBox, implement, review, steer, type ImplementResult, type ReviewResult } from "./agent.ts";
import { freePort, sh, OUT, SRC, WORK, type BoxInfo, type Mounts } from "./box.ts";
import { REVIEW_FACETS, facetPrompt, fixPrompt, implementPrompt, modelFor, rerankerPrompt, type Finding } from "./facets.ts";

export type ReviewRequest = {
	key: string; // the run's key; names the box, the agent sessions and the exported branch
	mode: "implement" | "review";
	repo: string; // absolute path to a git checkout on the host
	base: string; // e.g. "main"
	head: string; // review mode: the committed ref to review; implement mode: unused
	task: string; // implement mode: what to build; review mode: what the change was meant to do
	fixRounds?: number; // implement mode: fix-and-review cycles after the first review (default 1, as in OE)
};

type FacetOutcome = { ok: true; result: ReviewResult } | { ok: false; error: string };

/** One review of one commit: what each facet found, and what the reranker kept. */
export type Round = {
	round: number;
	headSha: string;
	diffStat: string;
	/** The implementation (round 0) or fix (later rounds) that produced headSha; none in review mode. */
	change: ImplementResult | null;
	facets: Record<string, FacetOutcome>;
	rerank: ReviewResult | null;
	kept: Finding[];
};

// LLM steps run for minutes; Rivet's default step timeout is 30s.
const AGENT_STEP = { timeout: 20 * 60_000, maxRetries: 1 };
// The implementer's edits live in the box; a blind retry would start over on
// top of them, so a failed implementation fails the run instead.
const IMPLEMENT_STEP = { timeout: 45 * 60_000, maxRetries: 0 };
const DEFAULT_FIX_ROUNDS = 1;

const RUNS = fileURLToPath(new URL("../runs", import.meta.url));
const IMPL = "/work/wt/impl";
const sessionId = (key: string, who: string) => `${key}-${who}`;
const worktree = (facet: string) => `/work/wt/${facet}`;
const branch = (key: string) => `agent/${key}`;

export const prReview = workflow({
	state: {
		status: "waiting" as "waiting" | "provisioning" | "implementing" | "fixing" | "reviewing" | "reranking" | "complete" | "failed",
		request: null as ReviewRequest | null,
		box: null as BoxInfo | null,
		outbox: "",
		baseSha: "",
		headSha: "",
		exportRef: "",
		round: 0,
		rounds: [] as Round[],
		/** Findings still open after the last round. */
		kept: [] as Finding[],
		error: "",
		startedAt: 0,
		finishedAt: 0,
	},
	queues: {
		review: queue<ReviewRequest>(),
	},
	run: async (ctx) => {
		const msg = await ctx.queue.next("wait-request");
		const req = msg.body;
		const implementing = req.mode === "implement";
		const fixRounds = implementing ? (req.fixRounds ?? DEFAULT_FIX_ROUNDS) : 0;

		try {
			// Resolved on the host, recorded once: every later step and every
			// replay sees the same commits even if the branch moves.
			const { box, baseSha, outbox, ...resolved } = await ctx.step("resolve", async (step) => {
				const git = (...a: string[]) => execFileSync("git", a, { cwd: req.repo, encoding: "utf8" }).trim();
				const outbox = `${RUNS}/${req.key}.git`;
				mkdirSync(RUNS, { recursive: true });
				execFileSync("git", ["init", "--quiet", "--bare", outbox]);
				const r = {
					box: { name: `review-${req.key}`, port: await freePort() },
					outbox,
					baseSha: implementing ? git("rev-parse", req.base) : git("merge-base", req.base, req.head),
					headSha: implementing ? "" : git("rev-parse", req.head),
				};
				step.state.request = req;
				step.state.startedAt = Date.now();
				step.state.status = "provisioning";
				Object.assign(step.state, r);
				return r;
			});
			const mounts: Mounts = { repo: req.repo, outbox };
			const vm = () => agentFor(box, mounts).box;
			const sdk = () => agentFor(box, mounts).sdk;

			const setStatus = (name: string, status: (typeof ctx.state)["status"]) =>
				ctx.step(name, async (step) => {
					step.state.status = status;
				});

			// One micro-VM per run: the host repo mounted read-only at /src, the
			// run's outbox (a bare repo on the host) writable at /out, and a clone in
			// /work/repo. Idempotent, so a replay reattaches and skips work done.
			await ctx.step({
				name: "provision-box",
				...AGENT_STEP,
				run: async () => {
					await sh(vm(), [
						`[ -d ${WORK} ] || git clone --quiet --no-checkout ${SRC} ${WORK}`,
						`git -C ${WORK} checkout --quiet --detach ${baseSha}`,
						...(implementing
							? [`[ -d ${IMPL} ] || git -C ${WORK} worktree add --quiet -b ${branch(req.key)} ${IMPL} ${baseSha}`]
							: []),
						...REVIEW_FACETS.map(
							(f) => `[ -d ${worktree(f.id)} ] || git -C ${WORK} worktree add --quiet --detach ${worktree(f.id)} ${baseSha}`,
						),
					].join(" && "));
					await sdk();
				},
			});

			/**
			 * Run the implementer (same session every round, so a fix turn keeps
			 * the context of the implementation), then commit and export. The
			 * workflow commits, not the agent: the SHA is recorded in step history,
			 * so reviewers and every replay see exactly this commit.
			 */
			const change = async (round: number, prompt: string, parent: string) => {
				const result = await ctx.step({
					name: `implement-r${round}`,
					...IMPLEMENT_STEP,
					run: async () =>
						implement({ sdk: await sdk(), sessionId: sessionId(req.key, "impl"), cwd: IMPL, model: "sonnet", prompt }),
				});
				const sha = await ctx.step(`commit-r${round}`, async () => {
					const subject = round === 0
						? `feat: ${req.task.split("\n")[0].slice(0, 60)}`
						: `fix: address review findings (round ${round})`;
					await sh(vm(), `cd ${IMPL} && git add -A && (git diff --cached --quiet || git commit --quiet -F -) <<'MSG'
${subject}

${result.summary.slice(0, 4000)}

Rivet-Run: ${req.key}
MSG`);
					return (await sh(vm(), `git -C ${IMPL} rev-parse HEAD`)).trim();
				});
				if (sha === parent) return { result, sha: null };
				// Export: the only write to the host, by the workflow, to the run's outbox.
				await ctx.step(`export-r${round}`, async (step) => {
					await sh(vm(), `git -C ${IMPL} push --quiet --force ${OUT} ${sha}:refs/heads/${branch(req.key)}`);
					step.state.headSha = sha;
					step.state.exportRef = `${outbox} ${branch(req.key)}`;
				});
				return { result, sha };
			};

			/** Five fresh reviewer sessions at `headSha`, then the reranker. */
			const reviewRound = async (round: number, headSha: string, changed: ImplementResult | null): Promise<Round> => {
				const diff = `the diff \`git diff ${baseSha}...${headSha}\` in this repository`;
				const diffStat = await ctx.step(`prepare-review-r${round}`, async (step) => {
					await sh(vm(), REVIEW_FACETS.map((f) => `git -C ${worktree(f.id)} checkout --quiet --detach ${headSha}`).join(" && "));
					step.state.status = "reviewing";
					step.state.round = round;
					return (await sh(vm(), `git -C ${WORK} diff --stat ${baseSha}...${headSha}`)).trim();
				});

				// Fan out: one durable branch per facet.
				const branches = Object.fromEntries(
					REVIEW_FACETS.map((facet) => [
						facet.id,
						{
							run: async (b: { tryStep: typeof ctx.tryStep }) => {
								const r = await b.tryStep({
									name: `review-${facet.id}-r${round}`,
									...AGENT_STEP,
									run: async () =>
										review({
											sdk: await sdk(),
											sessionId: sessionId(req.key, `${facet.id}-r${round}`),
											cwd: worktree(facet.id),
											model: modelFor(facet),
											prompt: facetPrompt(facet, diff, req.task),
										}),
								});
								return (r.ok
									? { ok: true, result: r.value }
									: { ok: false, error: String(r.failure.error?.message ?? r.failure.kind) }) as FacetOutcome;
							},
						},
					]),
				);
				const facets = (await ctx.join(`review-facets-r${round}`, branches as any)) as Record<string, FacetOutcome>;
				await setStatus(`reranking-r${round}`, "reranking");

				// Fan in: rerank across facets.
				const sections = REVIEW_FACETS.map((f) => {
					const o = facets[f.id];
					const body = o.ok ? JSON.stringify(o.result.findings, null, 2) : `(reviewer failed: ${o.error})`;
					return `## ${f.name} findings\n${body}\n`;
				}).join("\n");
				const rerank = await ctx.step({
					name: `rerank-r${round}`,
					...AGENT_STEP,
					run: async () =>
						review({
							sdk: await sdk(),
							sessionId: sessionId(req.key, `reranker-r${round}`),
							cwd: worktree(REVIEW_FACETS[0].id),
							model: "sonnet",
							prompt: rerankerPrompt(sections, diff, req.task, REVIEW_FACETS.length),
						}),
				});

				const result: Round = { round, headSha, diffStat, change: changed, facets, rerank, kept: rerank.findings };
				await ctx.step(`record-r${round}`, async (step) => {
					step.state.rounds.push(result);
					step.state.kept = result.kept;
				});
				return result;
			};

			// Round 0: implement (or take the ref under review), then review.
			let headSha = resolved.headSha;
			let changed: ImplementResult | null = null;
			if (implementing) {
				await setStatus("implementing", "implementing");
				const first = await change(0, implementPrompt(req.task), baseSha);
				if (!first.sha) throw new CriticalError("implementer made no changes");
				({ sha: headSha, result: changed } = first as { sha: string; result: ImplementResult });
			}
			let last = await reviewRound(0, headSha, changed);

			// Fix loop: kept findings go back to the implementer, the fix is
			// committed and exported, and the new head is reviewed afresh. It ends
			// when nothing is kept, the implementer changes nothing, or the rounds run out.
			for (let round = 1; round <= fixRounds && last.kept.length; round++) {
				await setStatus(`fixing-r${round}`, "fixing");
				const fix = await change(round, fixPrompt(last.kept, round), headSha);
				if (!fix.sha) {
					await ctx.step(`no-fix-r${round}`, async (step) => {
						step.state.rounds.push({ ...last, round, change: fix.result, facets: {}, rerank: null });
					});
					break;
				}
				headSha = fix.sha;
				last = await reviewRound(round, headSha, fix.result);
			}

			await ctx.step("finish", async (step) => {
				step.state.status = "complete";
				step.state.finishedAt = Date.now();
			});
			await ctx.step("close-box", () => closeBox(box, mounts));
		} catch (e) {
			// Exhausted retries, a timeout or a failed join end the run; anything
			// else (sleep, eviction, scheduled retry) is Rivet control flow.
			if (!(e instanceof StepExhaustedError || e instanceof CriticalError || e instanceof JoinError)) throw e;
			await ctx.step("fail", async (step) => {
				step.state.status = "failed";
				step.state.error = (e as any).lastError ?? e.message;
				step.state.finishedAt = Date.now();
			});
		}
	},
	actions: {
		getState: (c) => c.state,
		/** Queue a message for one agent ("impl", a facet, or "reranker"); delivered when its current turn ends. */
		steer: (c, who: string, text: string) => {
			if (!c.state.request) throw new Error("run has not started");
			// Reviewers get a fresh session each round; steer the current one.
			const target = who === "impl" ? who : `${who}-r${c.state.round}`;
			steer(sessionId(c.state.request.key, target), text);
			return { queuedFor: sessionId(c.state.request.key, target) };
		},
	},
});

export const registry = setup({ use: { prReview } });

