// Usage:
//   tsx src/client.ts implement <repo> <base> "<task>" [runKey] [--fix-rounds N]
//   tsx src/client.ts review    <repo> <base> <head> "<task>" [runKey]
import { setTimeout as sleep } from "node:timers/promises";
import { createClient } from "rivetkit/client";
import type { registry, ReviewRequest, Round } from "./registry.ts";

const argv = process.argv.slice(2);
const fixAt = argv.indexOf("--fix-rounds");
const fixRounds = fixAt >= 0 ? Number(argv.splice(fixAt, 2)[1]) : undefined;
const [mode, repo, base, ...rest] = argv;
const implementing = mode === "implement";
const [head, task, key = `r${Date.now()}`] = implementing ? ["", rest[0], rest[1]] : rest;
if ((mode !== "implement" && mode !== "review") || !repo || !base || !task) {
	console.error('usage: tsx src/client.ts implement <repo> <base> "<task>" [runKey] [--fix-rounds N]');
	console.error('       tsx src/client.ts review    <repo> <base> <head> "<task>" [runKey]');
	process.exit(2);
}

const client = createClient<typeof registry>(process.env.RIVET_ENDPOINT ?? "http://localhost:6420");
const handle = client.prReview.getOrCreate([key]);

// Right after `npm run server` the engine answers before its runner registers
// (no_runner_config_configured); retry through that window.
async function firstState() {
	for (let i = 0; ; i++) {
		try {
			return await handle.getState();
		} catch (e: any) {
			if (e?.code !== "no_runner_config_configured" || i >= 20) throw e;
			await sleep(1000);
		}
	}
}
