cd ~/code/rivet-eval && cat > src/persist.ts <<'EOF'
import { appendFileSync, existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { SessionEvent, SessionPersistDriver, SessionRecord } from "sandbox-agent";

/**
 * Sandbox Agent session records and event history as files on the host, one
 * pair per session under `dir`:
 *
 *   <session>.json          the SessionRecord
 *   <session>.events.jsonl  every SessionEvent (prompts, message chunks, tool calls, permissions)
 *
 * The SDK's default driver is in-memory, so transcripts died with the runner and
 * `resumeOrCreateSession` after a restart silently started a new session. Read
 * back on construction, this lets a restarted runner resume the same session.
 */
export class JsonlSessionPersistDriver implements SessionPersistDriver {
	private sessions = new Map<string, SessionRecord>();
	private events = new Map<string, SessionEvent[]>();

	constructor(private readonly dir: string) {
		mkdirSync(dir, { recursive: true });
		for (const f of readdirSync(dir)) {
			if (!f.endsWith(".json")) continue;
			const record: SessionRecord = JSON.parse(readFileSync(join(dir, f), "utf8"));
			this.sessions.set(record.id, record);
			const log = this.eventsFile(record.id);
			this.events.set(
				record.id,
				existsSync(log) ? readFileSync(log, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l)) : [],
			);
		}
	}

	private file = (id: string) => join(this.dir, `${encodeURIComponent(id)}.json`);
	private eventsFile = (id: string) => join(this.dir, `${encodeURIComponent(id)}.events.jsonl`);

	async getSession(id: string) {
		return this.sessions.get(id);
	}

	async listSessions(request?: { cursor?: string; limit?: number }) {
		return page([...this.sessions.values()], request);
	}

	async updateSession(session: SessionRecord) {
		this.sessions.set(session.id, session);
		writeFileSync(this.file(session.id), JSON.stringify(session, null, 2));
	}

	async listEvents(request: { sessionId: string; cursor?: string; limit?: number }) {
		return page(this.events.get(request.sessionId) ?? [], request);
	}

	async insertEvent(sessionId: string, event: SessionEvent) {
		const list = this.events.get(sessionId) ?? [];
		list.push(event);
		this.events.set(sessionId, list);
		appendFileSync(this.eventsFile(sessionId), `${JSON.stringify(event)}\n`);
	}
}

function page<T>(items: T[], request?: { cursor?: string; limit?: number }) {
	const start = Number(request?.cursor ?? 0);
	const end = request?.limit ? start + request.limit : items.length;
	return { items: items.slice(start, end), nextCursor: end < items.length ? String(end) : undefined };
}
EOF
